fn input(p:&Path)->Inputs{let manifest=p.join("logs/continuation-20261003/r486-map-binding.json");let b=fs::read(&manifest).unwrap();Inputs{project:p.into(),manifest,manifest_pin:BytePin{bytes:b.len()as u64,sha256:Sha256::digest(b).into()}}}
fn wait(mut f:impl FnMut()->bool){let end=Instant::now()+Duration::from_secs(60);while !f(){assert!(Instant::now()<end,"R489 bounded new state flow wait");thread::sleep(Duration::from_millis(2));}}
fn bytes(v:&Value)->Vec<u8>{v.as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as u8).collect()}
fn delta(id:u32,mode:u8)->Vec<u8>{let mut p=vec![213,2];p.extend(id.to_le_bytes());p.push(mode);p}
fn outcome(o:SnapshotOutcome)->Value{match o{SnapshotOutcome::IgnoredIdentifier=>json!({"kind":"IgnoredIdentifier"}),SnapshotOutcome::Applied{mode:Outcome::Applied{previous,current,identifier_rebound},native_phase_after}=>json!({"kind":"Applied","previous":previous,"current":current,"identifier_rebound":identifier_rebound,"native_phase_after":native_phase_after}),_=>panic!("invalid snapshot outcome")}}
fn decoded(s:&Snapshot)->Value{let mut strings=Vec::new();let mut words=Vec::new();let mut extension=None;for f in s.fields(){match &f.value{FieldValue::Bytes(b)if f.destination=="byte_64ACD8"=>extension=Some(b.clone()),FieldValue::Bytes(b)=>strings.push(b.clone()),FieldValue::Word(w)=>words.push(*w),_=>{}}}json!({"kind":format!("{:?}",s.kind()),"identifier":s.identifier(),"mode_byte":s.mode_byte(),"strings":strings,"words":words,"extension":extension})}
fn presentation(rt:&Runtime)->Value{let m=rt.menu().unwrap();json!({"page":format!("{:?}",rt.page()),"status":rt.status(),"filter":format!("{:?}",m.filter),"rows":format!("{:?}",m.rows()),"top":m.top,"menu_selected":m.selected,"selected_index":rt.selected_index(),"choice":rt.choice().map(|c|(c.mode,c.map_id)),"pressed":m.pressed.map(|h|format!("{h:?}")),"repeat_due":m.repeat_deadline(),"frame_identity":rt.frame().map(|f|f.identity()),"pan_pending":rt.pan_pending()})}
fn reset(rt:&Runtime,mode:u8){let m=rt.menu().unwrap();assert_eq!(m.filter,Filter::Mode{mode,alternate:false});assert_eq!((m.top,m.selected,m.pressed,m.repeat_deadline()),(0,None,None,None));assert!(rt.choice().is_none());assert!(rt.frame().is_none());assert_eq!(rt.page(),UiPage::Menu);assert_eq!(rt.status(),"請選擇場地");}
