 rt.apply_native_state_packet(&matching,ctx2)?;assert_eq!(rt.native_mode().raw_mode(),3);same_snapshot(&rt,&matching);rt.open_native_mode_menu()?;reset(&rt,3);flow.push(json!({"case":"213 subtype0 variable raw strings -> explicit mode3 menu","decoded":decoded(&rt.native_snapshot().unwrap()),"after":presentation(&rt),"passed":true}));
 rt.handle(Action::Select(3,563))?;rt.menu_mut().unwrap().top=1;rt.menu_mut().unwrap().down_at(Some(Hit::Down),2000);let before=presentation(&rt);let context=rt.native_mode();assert!(rt.apply_native_state_packet(&malformed,ctx6).is_err());assert!(rt.apply_native_state_packet(&blocked,Context{phase:6,dispatch_word:4}).is_err());assert_eq!(rt.native_mode(),context);same_snapshot(&rt,&matching);assert_eq!(presentation(&rt),before);flow.push(json!({"case":"late extension truncation and unavailable dispatcher refuse atomically before new identifier","before":before,"after":presentation(&rt),"passed":true}));
